all_data = {}

def get_info_1(number):
    url = 'https://zakupki.gov.ru/epz/capitalrepairs/card/general-info.html?reestr-number='+number
    response = requests.get(url=url, headers=headers.generate())
    soup = bs(response.content, 'html.parser')
    contract_number = soup.select_one('body > div.cardWrapper.outerWrapper > div > div.cardHeaderBlock > '
                                      'div:nth-child(3) > div.search-results > div > div > div > div.col-6.pr-0 > '
                                      'div.registry-entry__body > div:nth-child(1) > '
                                      'div.registry-entry__body-value').text.strip()
    contract_date = soup.select_one('body > div.cardWrapper.outerWrapper > div > div.cardHeaderBlock > div:nth-child('
                                    '3) > div.search-results > div > div > div > '
                                    'div.col-3.d-flex.flex-column.registry-entry__right-block.b-left > '
                                    'div.data-block.mt-auto > div:nth-child(2)').text.strip()
    contractor_name = soup.select_one('body > div.cardWrapper.outerWrapper > div > div:nth-child(10) > div > div > '
                                      'div > section:nth-child(1) > span.section__info').text.strip()
    contractor_inn = soup.select_one('body > div.cardWrapper.outerWrapper > div > div:nth-child(10) > div > div > div > section:nth-child(2) > span.section__info').text.strip()
    all_data[number] = {}
    all_data[number]["Номер контракта"] = (contract_number)
    all_data[number]["Дата контракта"] = contract_date
    all_data[number]["Поставщик"] = contractor_name
    all_data[number]["ИНН"] = contractor_inn
    all_data[number]["Адреса"] = {}


def get_info_2(number):
    pages = True
    page = 1
    num = 0
    while pages:
        url = f'https://zakupki.gov.ru/epz/capitalrepairs/card/finance-info-list.html?reestrNumber={number}' \
              f'&page={page}&pageSize=100'
        response = requests.get(url=url, headers=headers.generate())
        soup = bs(response.content, 'html.parser')
        try:
            list_orders = soup.find('tbody').find_all('tr')
            for one_row_order in list_orders:
                one_row_data = [x.text.strip() for x in one_row_order.find_all('td')]
                house_addres = one_row_data[1]
                house_kind_repare = one_row_data[2]
                kind_price = one_row_data[-1]
                all_data[number]["Адреса"][num] = {
                    "Адрес": house_addres,
                    "Вид ремонта": house_kind_repare,
                    "Цена": kind_price
                }
                num += 1
            page += 1
        except:
            pages = False
            continue

def save_data():
    with open('data_contactor.json', 'a', encoding='utf-8') as js_file:
        json.dump(all_data, js_file, ensure_ascii=False, indent=4)

def main():
    for num in numbers_orders:
        get_info_1(num)
        get_info_2(num)
        print(f'{num} --- Завершен!')
    save_data()
if __name__ == '__main__':
    main()